package br.com.catalogo;
import org.apache.pdfbox.Loader;import org.apache.pdfbox.pdmodel.PDDocument;import org.apache.pdfbox.rendering.PDFRenderer;
import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.util.*;

/** Leitor PDF com rolagem contínua, renderização sob demanda e página retomada automaticamente. */
final class PdfReader extends JFrame {
 private PDDocument document;private final Biblioteca library;private final Biblioteca.Book book;private final Runnable changed;
 private final JLabel status=new JLabel(" ");
 private final JSpinner page=new JSpinner(new SpinnerNumberModel(1,1,1000000,1));private final JButton previous=new JButton("← Anterior"),next=new JButton("Próxima →");
 private final JComboBox<String> zoom=new JComboBox<>(new String[]{"Ajustar à largura","100%","125%","150%"});private final JProgressBar progress=new JProgressBar();
 private final JPanel pagesPanel=new JPanel();private final JScrollPane viewport=new JScrollPane(pagesPanel);private final java.util.List<JLabel> pages=new ArrayList<>();
 private boolean rendering=false,closing=false,navigating=false;private int renderingPage=-1,visiblePage=1,lastSavedPage=-1,lastSavedPosition=-1,renderGeneration;private final javax.swing.Timer resizeDelay,scrollDelay;
 private static final String PDF_POSITION="pdf-scroll:";
 PdfReader(JFrame owner,Biblioteca lib,Biblioteca.Book b,Runnable changed){
  super(b.display());library=lib;book=b;this.changed=changed;setIconImage(UiTheme.appIcon());setResizable(true);setMinimumSize(new Dimension(640,480));setSize(1000,850);setLocationRelativeTo(owner);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
  var bar=new JPanel(new FlowLayout(FlowLayout.CENTER,12,10));bar.add(previous);bar.add(new JLabel("Página"));bar.add(page);bar.add(next);bar.add(zoom);progress.setIndeterminate(true);progress.setVisible(false);bar.add(progress);add(bar,BorderLayout.NORTH);
  pagesPanel.setLayout(new BoxLayout(pagesPanel,BoxLayout.Y_AXIS));pagesPanel.setBackground(UiTheme.SURFACE);viewport.getViewport().setBackground(UiTheme.SURFACE);add(viewport);status.setBorder(BorderFactory.createEmptyBorder(8,14,8,14));add(status,BorderLayout.SOUTH);
  viewport.getVerticalScrollBar().setUnitIncrement(18);viewport.getVerticalScrollBar().setBlockIncrement(120);
  previous.addActionListener(e->goToPage(Math.max(1,visiblePage-1)));next.addActionListener(e->{if(document!=null)goToPage(Math.min(document.getNumberOfPages(),visiblePage+1));});
  page.addChangeListener(e->{if(!navigating&&document!=null){int selected=(Integer)page.getValue();if(selected!=visiblePage)goToPage(selected);}});zoom.addActionListener(e->refreshPageSizes(true));
  scrollDelay=new javax.swing.Timer(45,e->onScroll());scrollDelay.setRepeats(false);viewport.getVerticalScrollBar().addAdjustmentListener(e->{if(!closing)scrollDelay.restart();});
  resizeDelay=new javax.swing.Timer(180,e->refreshPageSizes(true));resizeDelay.setRepeats(false);viewport.getViewport().addComponentListener(new ComponentAdapter(){public void componentResized(ComponentEvent e){if(!closing)resizeDelay.restart();}});
  getRootPane().registerKeyboardAction(e->previous.doClick(),KeyStroke.getKeyStroke(KeyEvent.VK_LEFT,0),JComponent.WHEN_IN_FOCUSED_WINDOW);getRootPane().registerKeyboardAction(e->next.doClick(),KeyStroke.getKeyStroke(KeyEvent.VK_RIGHT,0),JComponent.WHEN_IN_FOCUSED_WINDOW);
  addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){closing=true;resizeDelay.stop();scrollDelay.stop();if(!rendering)finish();}});
  new SwingWorker<PDDocument,Void>(){protected PDDocument doInBackground()throws Exception{return Loader.loadPDF(library.file(book).toFile());}protected void done(){try{document=get();if(closing){finish();return;}int count=document.getNumberOfPages(),resume=Math.min(Math.max(1,book.page),count);page.setModel(new SpinnerNumberModel(resume,1,count,1));for(int i=0;i<count;i++){var label=new JLabel("Página "+(i+1),SwingConstants.CENTER);label.setOpaque(true);label.setBackground(Color.WHITE);label.setForeground(UiTheme.MUTED);label.setAlignmentX(Component.CENTER_ALIGNMENT);label.setBorder(BorderFactory.createEmptyBorder(0,0,14,0));pages.add(label);pagesPanel.add(label);}refreshPageSizes(false);int offset=resumeOffset(book.location,resume);SwingUtilities.invokeLater(()->goToPage(resume,offset));}catch(Exception e){JOptionPane.showMessageDialog(PdfReader.this,"Não foi possível abrir: "+e.getMessage());dispose();}}}.execute();
 }
 private float dpi(int index){var box=document.getPage(index).getCropBox();float width=box.getWidth();int rotation=document.getPage(index).getRotation();if(rotation%180!=0)width=box.getHeight();return zoom.getSelectedIndex()==0?Math.max(36,Math.min(240,(Math.max(500,viewport.getViewport().getWidth())-36)*72f/width)):72*(zoom.getSelectedIndex()==1?1:zoom.getSelectedIndex()==2?1.25f:1.5f);}
 private Dimension pageSize(int index,float dpi){var box=document.getPage(index).getCropBox();double width=box.getWidth(),height=box.getHeight();if(document.getPage(index).getRotation()%180!=0){double swap=width;width=height;height=swap;}return new Dimension((int)Math.ceil(width*dpi/72),(int)Math.ceil(height*dpi/72));}
 private void refreshPageSizes(boolean rerender){if(document==null||closing)return;int anchor=Math.max(0,Math.min(visiblePage-1,pages.size()-1));double fraction=0;if(rerender&&pages.get(anchor).getHeight()>14){Rectangle visible=viewport.getViewport().getViewRect();fraction=Math.max(0,Math.min(1d,(visible.y-pages.get(anchor).getY())/(double)(pages.get(anchor).getHeight()-14)));}if(rerender)renderGeneration++;for(int i=0;i<pages.size();i++){JLabel label=pages.get(i);Dimension size=pageSize(i,dpi(i));int width=Math.max(viewport.getViewport().getWidth(),size.width+36);label.setPreferredSize(new Dimension(width,size.height+14));label.setMinimumSize(new Dimension(width,size.height+14));label.setMaximumSize(new Dimension(Integer.MAX_VALUE,size.height+14));if(rerender){label.setIcon(null);label.setText("Página "+(i+1));}}pagesPanel.revalidate();pagesPanel.repaint();if(rerender){int selected=anchor;double position=fraction;SwingUtilities.invokeLater(()->{if(closing)return;viewport.validate();Rectangle bounds=pages.get(selected).getBounds();JScrollBar bar=viewport.getVerticalScrollBar();int offset=(int)Math.round((pages.get(selected).getHeight()-14)*position);bar.setValue(Math.max(0,Math.min(bar.getMaximum()-bar.getVisibleAmount(),bounds.y+offset)));scrollDelay.restart();});}}
 private void goToPage(int target){goToPage(target,0);}
 private void goToPage(int target,int offset){if(document==null||closing)return;target=Math.max(1,Math.min(target,document.getNumberOfPages()));visiblePage=target;navigating=true;page.setValue(target);navigating=false;int index=target-1;SwingUtilities.invokeLater(()->{if(closing)return;Rectangle bounds=pages.get(index).getBounds();JScrollBar bar=viewport.getVerticalScrollBar();bar.setValue(Math.max(0,Math.min(bar.getMaximum()-bar.getVisibleAmount(),bounds.y+Math.max(0,offset))));scrollDelay.restart();});}
 private void onScroll(){if(document==null||closing)return;Rectangle visible=viewport.getViewport().getViewRect();int top=-1;for(int i=0;i<pages.size();i++){if(pages.get(i).getBounds().intersects(visible)){top=i;break;}}if(top<0)return;visiblePage=top+1;navigating=true;page.setValue(visiblePage);navigating=false;Rectangle pageBounds=pages.get(top).getBounds();int offset=Math.max(0,visible.y-pageBounds.y);int position=(int)Math.min(1000000L,Math.round(1000000d*offset/Math.max(1,pages.get(top).getPreferredSize().height-14)));String location=PDF_POSITION+visiblePage+":"+position;if(lastSavedPage!=visiblePage||lastSavedPosition!=position){try{library.saveProgress(book,visiblePage,location);lastSavedPage=visiblePage;lastSavedPosition=position;changed.run();status.setText("Página "+visiblePage+" de "+document.getNumberOfPages()+" · posição salva automaticamente");}catch(Exception e){status.setText("Falha ao salvar o progresso: "+e.getMessage());}}renderVisible(top,visible);}
 private int resumeOffset(String value,int page){try{var parts=value.split(":");if(parts.length!=3||!parts[0].equals("pdf-scroll")||Integer.parseInt(parts[1])!=page)return 0;int fraction=Math.max(0,Math.min(1000000,Integer.parseInt(parts[2])));return (int)Math.round((pages.get(page-1).getPreferredSize().height-14)*fraction/1000000d);}catch(Exception e){return 0;}}
 private void renderVisible(int top,Rectangle visible){if(rendering||closing)return;int candidate=-1;for(int i=Math.max(0,top-1);i<Math.min(pages.size(),top+5);i++){if(pages.get(i).getIcon()==null){candidate=i;break;}}if(candidate<0)return;rendering=true;renderingPage=candidate;int target=candidate;float targetDpi=dpi(candidate);progress.setVisible(true);
  int generation=renderGeneration;new SwingWorker<ImageIcon,Void>(){protected ImageIcon doInBackground()throws Exception{return new ImageIcon(new PDFRenderer(document).renderImageWithDPI(target,targetDpi));}protected void done(){try{if(!closing&&generation==renderGeneration){pages.get(target).setText("");pages.get(target).setIcon(get());}}catch(Exception e){if(!closing)status.setText("Falha ao renderizar a página "+(target+1)+": "+e.getMessage());}finally{rendering=false;renderingPage=-1;progress.setVisible(false);if(closing)finish();else{trimRenderedPages();scrollDelay.restart();}}}}.execute();
 }
 private void trimRenderedPages(){Rectangle visible=viewport.getViewport().getViewRect();for(int i=0;i<pages.size();i++){var label=pages.get(i);if(!label.getBounds().intersects(visible)&&Math.abs(i+1-visiblePage)>4&&label.getIcon()!=null){label.setIcon(null);label.setText("Página "+(i+1));}}}
 private void finish(){resizeDelay.stop();scrollDelay.stop();try{if(document!=null){document.close();document=null;}dispose();}catch(Exception e){status.setText(e.getMessage());}}
}
